const API_BASE_URL = "http://localhost:8081/api";

async function handleRequest(url, options) {
  try {
    const response = await fetch(url, options);

    // If backend is reachable but returns an error status
    if (!response.ok) {
      let errorText;
      try {
        // Try to parse as JSON first
        const errorData = await response.json();
        errorText = errorData.message || JSON.stringify(errorData);
      } catch {
        // Fallback to text if not JSON
        errorText = await response.text();
      }
      throw new Error(errorText || "Request failed");
    }

    // Return JSON if success
    return await response.json();
  } catch (err) {
    // This catches "Failed to fetch" or network errors
    if (err.name === "TypeError" && err.message === "Failed to fetch") {
      throw new Error("Cannot connect to the server. Please check if the backend is running.");
    }
    throw err;
  }
}

export async function login(email, password) {
  return handleRequest(`${API_BASE_URL}/auth/login`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email, password }),
  });
}

export async function signup(data) {
  const userPayload = {
    username: data.username,
    email: data.email,
    passwordHash: data.password,
    firstName: "Temp",
    lastName: "User",
    phone: "0000000000",
    role: "DEFAULT_USER",
  };

  return handleRequest(`${API_BASE_URL}/auth/signup`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(userPayload),
  });
}
